function apsError(start) {
    node.status('Error start at: ' + start);
    throw new Error(`Données insuffisantes à la position ${start}`);
}

function apsStr(buffer, start, amount) {
    if ((start + amount) > buffer.length) apsError(start);

    return buffer.subarray(start, start + amount).toString('utf8');
}

function apsUid(buffer, start) {
    if ((start + 12) > buffer.length) apsError(start);

    return buffer.subarray(start, start + 12).toString('hex').slice(0, 12);
}

function apsInt(buffer, start) {
    if ((start + 2) > buffer.length) apsError(start);

    return buffer.readUInt16BE(start);
}

function apsDouble(buffer, start) {
    if ((start + 4) > buffer.length) apsError(start);

    return buffer.readUInt32BE(start);
}

function apsShort(buffer, start) {
    try {
        return parseInt(buffer.subarray(start, start + 1).toString('hex'), 8);
    } catch (err) {
        apsError(start);
    }
}

if (typeof msg.data !== 'object') {
    // Grab known ECU IP
    let units = global.get('units', 'default');
    if (typeof units === 'object') {
        for (const name in units) {
            node.send([{
                'topic': name,
                'host': units[name]['ip'],
                'port': '8899',
                'payload': "APS1100160001" + "END\n",
                'data': {}
            }, null]);
        }
    }

    return;
}

if (typeof msg.data.ecu !== 'object') {

    // Parse ECU data
    let buf = Buffer.from(msg.payload);
    node.status({ text: 'buffer length: ' + buf.length});

    msg.data = {
        'ecu': {
            'id': '',
            'name': msg.topic,
            'host': msg.host,
            'port': msg.port,
            'type': 0,
            'energy_total': 0,
            'energy_total_unit': 'kWh',
            'energy_today': 0,
            'energy_today_unit': 'kWh',
            'power_instant': 0,
            'power_instant_unit': 'W',
            'inverters_quantity': 0,
            'inverters_online': 0
        }
    }

    if (apsStr(buf, 9, 4) === "0001") {
        msg.data.ecu.id = apsStr(buf, 13, 12);
        msg.data.ecu.type = parseInt(apsStr(buf, 25, 2), 10); // 1 or 2
        msg.data.ecu.energy_total = apsDouble(buf, 27) / 10;
        msg.data.ecu.power_instant = apsDouble(buf, 31)
        msg.data.ecu.energy_today = apsDouble(buf, 35) / 100;

        if (msg.data.ecu.type === 1) {
            msg.data.ecu.inverters_quantity = apsInt(buf, 46);
            msg.data.ecu.inverters_online = apsInt(buf, 48);

            let offset_f = parseInt(apsStr(buf, 52, 3), 10);
            msg.data.ecu.firmware = apsStr(buf, 55, offset_f);
            let offset_t = parseInt(apsStr(buf, 55 + offset_f, 3), 10);
            msg.data.ecu.timezone = apsStr(buf, 58 + offset_f, offset_t);

        }
        else if (msg.data.ecu.type === 2) {
            msg.data.ecu.inverters_quantity = apsInt(buf, 39);
            msg.data.ecu.inverters_online = apsInt(buf, 41);

            let offset_f = parseInt(apsStr(buf, 49, 3), 10);
            msg.data.ecu.firmware = apsStr(buf, 52, offset_f);
        }

        // prepare Inverter query
        if (msg.data.ecu.inverters_quantity > 0) {
            msg.payload = "APS1100280002" + msg.data.ecu.id + "END\n";

            node.send([msg, null]);
        } else {
            node.send([null, msg]);
        }
    }

    return
}
else {

    // Parse Inverter data
    let buf = Buffer.from(msg.payload);
    node.status({ text: 'buffer length: ' + buf.length});

    msg.data.inverters = {}

    if (apsStr(buf, 9, 4) === "0002") {
        let offset1 = 0;
        let offset2 = 26;

        if (apsStr(buf, 14, 2) == "00") {
            while (offset1 < apsInt(buf, 17)) {
                if (apsStr(buf, 15, 2) == "01") {

                    msg.data.inverters[offset1] = {
                        'id': apsUid(buf, offset2),
                        'type': Number(apsStr(buf, offset2 + 7, 2)),
                        'online': apsShort(buf, offset2 + 6),
                        'temperature': 0,
                        'power': [],
                        'voltage': []
                    };

                    // common
                    if (msg.data.inverters[offset1]['type'] in [1, 2, 3, 4, 5]) {
                        msg.data.inverters[offset1]['frequency'] = apsInt(buf, offset2 + 9) / 10;

                        if (msg.data.inverters[offset1]['online'] === 1) {
                            msg.data.inverters[offset1]['temperature'] = apsInt(buf, offset2 + 11) - 100;
                        }
                        msg.data.inverters[offset1]['power'][0] = apsInt(buf, offset2 + 13);
                        msg.data.inverters[offset1]['voltage'][0] = apsInt(buf, offset2 + 15);
                    }

                    if (msg.data.inverters[offset1]['type'] in [1, 4, 5]) {

                        msg.data.inverters[offset1]['model'] = 'YC600/DS3D/DS3-H/DS3/DS3-L';
                        msg.data.inverters[offset1]['chanel'] = 2;
                        msg.data.inverters[offset1]['max'] = 2000; // YC600=600VA,DS3D=2000VA,DS3-H=960VA, DS3=880VA, DS3-L=730VA
                        msg.data.inverters[offset1]['power'][1] = apsInt(buf, offset2 + 17);
                        msg.data.inverters[offset1]['voltage'][1] = apsInt(buf, offset2 + 19);

                        offset2 = offset2 + 21;
                    }
                    else if (msg.data.inverters[offset1]['type'] === 2) {

                        msg.data.inverters[offset1]['model'] = 'YC1000/QT2';
                        msg.data.inverters[offset1]['chanel'] = 4;
                        msg.data.inverters[offset1]['max'] = 2000; // YC1000=1000VA, QT2=2000VA
                        msg.data.inverters[offset1]['power'][1] = apsInt(buf, offset2 + 17);
                        msg.data.inverters[offset1]['voltage'][1] = apsInt(buf, offset2 + 19);
                        msg.data.inverters[offset1]['power'][2] = apsInt(buf, offset2 + 21);
                        msg.data.inverters[offset1]['voltage'][2] = apsInt(buf, offset2 + 23);
                        msg.data.inverters[offset1]['power'][3] = apsInt(buf, offset2 + 25);

                        offset2 = offset2 + 27;
                    }
                    else if (msg.data.inverters[offset1]['type'] === 3) {

                        msg.data.inverters[offset1]['model'] = 'QS1';
                        msg.data.inverters[offset1]['chanel'] = 4;
                        msg.data.inverters[offset1]['max'] = 1200; // QS1=1200VA
                        msg.data.inverters[offset1]['power'][1] = apsInt(buf, offset2 + 17);
                        msg.data.inverters[offset1]['power'][2] = apsInt(buf, offset2 + 19);
                        msg.data.inverters[offset1]['power'][3] = apsInt(buf, offset2 + 21);

                        offset2 = offset2 + 23;
                    }
                    else {
                        offset2 = offset2 + 9;
                    }
                }

                offset1++;
            }
        }
    }

    // CLeanup
    delete msg.host;
    delete msg.port;
    msg.topic = global.get('mqtt.topic', 'default') + '/' + msg.topic;
    msg.payload = msg.data;

    // Global
    let controls = global.get('controls', 'default');
    if (typeof controls !== 'object') {
        controls = {}
    }
    controls[msg.payload.ecu.name] = msg.payload;
    global.set('controls', controls, 'default');

    node.send([null, msg]);

    return;
}

